inter = fset & oset
# allowlist: proper nouns / industry terms
allow_words = {'searates','tracking','api','apis','carrier','carriers','edi','ais','json','utc','tms','et a','eta','etas','crm','crms','erp','erps','dcsa','gate','in','loaded','departed','container','received','milestone','milestones','real','time','supply','chain','logistics','data','shipment','shipments'}
def is_term(g):
    return all(w in allow_words or len(w)<2 for w in g)
bad = [g for g in inter if not is_term(g)]
